head.b:skin:
/* 
-----------------------------------------------
Blogger Template Style
Name:        Speedify
Version:     1.0
Author:      Templateify
Author Url:  https://www.templateify.com/
----------------------------------------------- */

/*
<!-- Variable definitions -->
<Variable name="keycolor" description="Main Color" type="color" default="#dc2833" value="#dc2833"/>

<Group description="Adjust Widths" selector="body">
  <Variable name="row.width" description="Main Container Width" type="length" default="960px" min="960px" max="1060px" value="960px"/>
</Group>

<Group description="Main Theme Colors" selector="body">
  <Variable name="main.color" description="Theme Color" type="color" default="#dc2833" value="#dc2833"/>
  <Variable name="dark.color" description="Dark Color" type="color" default="#1f2024" value="#1f2024"/>
  <Variable name="link.color" description="Links Color" type="color" default="#1f2024" value="#1f2024"/>
  <Variable name="link.hover.color" description="Links Hover Color" type="color" default="$(main.color)" value="#dc2833"/>
</Group>

<Group description="Theme Body" selector="body">
  <Variable name="body.background.color" description="Body background color" type="color" default="#f8f8f8"  value="#f8f8f8"/>
  <Variable name="body.background" description="Background" type="background" color="#e9eaed" default="$(color) url() repeat scroll top left" value="$(color) url() repeat scroll top left"/>
  <Variable name="outer.bg" description="Outer Wrapper BG" type="color" default="#f5f5f5"  value="#f5f5f5"/>
  <Variable name="body.text.color" description="Body Text Color" type="color" default="#5E5E5E"  value="#5E5E5E"/>
  <Variable name="body.link.color" description="Body Link Color" type="color" default="$(main.color)"  value="#dc2833"/>
</Group>

<Group description="Main Menu" selector="#header-wrap">
  <Variable name="menu.bg" description="Menu Background" type="color" default="$(dark.color)" value="#1f2024"/>
  <Variable name="menu.color" description="Menu Color" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="menu.hover.color" description="Menu Hover Color" type="color" default="$(main.color)" value="#dc2833"/>
  <Variable name="sub.menu.bg" description="SubMenu BG" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="sub.menu.color" description="SubMenu Color" type="color" default="#1f2024" value="#1f2024"/>
  <Variable name="sub.menu.hover.color" description="SubMenu Hover Color" type="color" default="$(main.color)" value="#dc2833"/>
  <Variable name="sub.menu.post.title.hover.color" description="SubMenu Post Title Hover Color" type="color" default="$(sub.menu.hover.color)" value="#dc2833"/>
</Group>

<Group description="Mobile Menu">
  <Variable name="mobile.menu.bg" description="Mobile Menu BG" type="color" default="$(dark.color)" value="#1f2024"/>
  <Variable name="mobile.menu.color" description="Mobile Menu Color" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="mobile.menu.hover.color" description="Mobile Menu Hover Color" type="color" default="$(main.color)" value="#dc2833"/>
</Group>

<Group description="Blog Posts" select="#main-wrapper">
  <Variable name="posts.background.color" description="Post Background" type="color" default="#ffffff"  value="#ffffff"/>
  <Variable name="post.title.color" description="Post Title Color" type="color" default="#1f2024" value="#1f2024"/>
  <Variable name="post.title.hover.color" description="Post Title Hover Color" type="color" default="$(main.color)" value="#dc2833"/>
  <Variable name="post.text.color" description="Post Text Color" type="color" default="$(body.text.color)" value="#5E5E5E"/>
  <Variable name="meta.color" description="Post Meta Color" type="color" default="#aaaaaa" value="#aaaaaa"/>
  <Variable name="post.snip.color" description="Post Snippet Color" type="color" default="#454545" value="#454545"/>
</Group>

<Group description="Author Box">
  <Variable name="author.box.bg" description="Author Box Background" type="color" default="$(dark.color)" value="#1f2024"/>
  <Variable name="author.title" description="Author Title" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="author.title.hover.color" description="Author Title Hover Color" type="color" default="$(main.color)" value="#dc2833"/>
  <Variable name="author.text.color" description="Author Text Color" type="color" default="#aaaaaa" value="#aaaaaa"/>
</Group>

<Group description="Theme Sidebar" selector="#sidebar-wrapper">
  <Variable name="sidebar.widget.bg" description="Widget Background" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="sidebar.title.bg" description="Widget Title Background" type="color" default="$(dark.color)" value="#1f2024"/>
  <Variable name="sidebar.title.color" description="Widget Title Color" type="color" default="#ffffff" value="#ffffff"/>
</Group>

<Group description="Theme Buttons">
  <Variable name="button1.bg" description="Button1 BG" type="color" default="$(main.color)" value="#dc2833"/>
  <Variable name="button1.color" description="Button1 Color" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="button2.bg" description="Button2 BG" type="color" default="$(dark.color)" value="#1f2024"/>
  <Variable name="button2.color" description="Button2 Color" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="button3.bg" description="Button3 BG" type="color" default="#f7f8f9" value="#f7f8f9"/>
  <Variable name="button3.color" description="Button3 Color" type="color" default="#1f2024" value="#1f2024"/>
</Group>

<Group description="Theme Footer" selector=".footer-widgets-wrap">
  <Variable name="footer.bg" description="Footer Background" type="color" default="$(dark.color)" value="#1f2024"/>
  <Variable name="footer.color" description="Footer Color" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="footer.hover.color" description="Footer Links Hover Color" type="color" default="$(link.hover.color)" value="#dc2833"/>
  <Variable name="footer.post.title.hover.color" description="Footer Post Title Hover Color" type="color" default="$(main.color)" value="#dc2833"/>
  <Variable name="footer.text.color" description="Footer Text Color" type="color" default="#aaaaaa" value="#aaaaaa"/>
</Group>

<Group description="Footer Bar" selector="#sub-footer-wrapper">
  <Variable name="footer.bar.bg" description="Footer Bar Background" type="color" default="#18191d" value="#18191d"/>
  <Variable name="footer.bar.color" description="Footer Bar Color" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="footer.bar.hover.color" description="Footer Bar Links Hover Color" type="color" default="$(link.hover.color)" value="#dc2833"/>
</Group>

<!-- Extra Variables -->
<Variable name="body.text.font" description="Font" hideEditor="true" type="font" default="14px Lato, sans-serif"  value="14px Lato, sans-serif"/>
<Variable name="tabs.font" description="Font 2" hideEditor="true" type="font" default="700 14px Lato, sans-serif"  value="700 14px Lato, sans-serif"/>
<Variable name="posts.title.color" description="Post title color" hideEditor="true" type="color" default="$(post.title.color)"  value="#1f2024"/>
<Variable name="posts.text.color" description="Post text color" hideEditor="true" type="color" default="$(post.text.color)"  value="#5E5E5E"/>
<Variable name="posts.icons.color" description="Post icons color" hideEditor="true" type="color" default="$(main.color)"  value="#dc2833"/>
<Variable name="labels.background.color" description="Label background color" hideEditor="true" type="color" default="$(main.color)"  value="#dc2833"/>
*/

/*-- Google Fonts --*/
@font-face{font-family:'Lato';font-style:italic;font-weight:400;src:local('Lato Italic'),local(Lato-Italic),url(https://fonts.gstatic.com/s/lato/v14/S6u8w4BMUTPHjxsAUi-qJCY.woff2) format("woff2");unicode-range:U+0100-024F,U+0259,U+1E00-1EFF,U+2020,U+20A0-20AB,U+20AD-20CF,U+2113,U+2C60-2C7F,U+A720-A7FF}
@font-face{font-family:'Lato';font-style:italic;font-weight:400;src:local('Lato Italic'),local(Lato-Italic),url(https://fonts.gstatic.com/s/lato/v14/S6u8w4BMUTPHjxsAXC-q.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+2000-206F,U+2074,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}
@font-face{font-family:'Lato';font-style:italic;font-weight:700;src:local('Lato Bold Italic'),local(Lato-BoldItalic),url(https://fonts.gstatic.com/s/lato/v14/S6u_w4BMUTPHjxsI5wq_FQft1dw.woff2) format("woff2");unicode-range:U+0100-024F,U+0259,U+1E00-1EFF,U+2020,U+20A0-20AB,U+20AD-20CF,U+2113,U+2C60-2C7F,U+A720-A7FF}
@font-face{font-family:'Lato';font-style:italic;font-weight:700;src:local('Lato Bold Italic'),local(Lato-BoldItalic),url(https://fonts.gstatic.com/s/lato/v14/S6u_w4BMUTPHjxsI5wq_Gwft.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+2000-206F,U+2074,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}
@font-face{font-family:'Lato';font-style:normal;font-weight:400;src:local('Lato Regular'),local(Lato-Regular),url(https://fonts.gstatic.com/s/lato/v14/S6uyw4BMUTPHjxAwXjeu.woff2) format("woff2");unicode-range:U+0100-024F,U+0259,U+1E00-1EFF,U+2020,U+20A0-20AB,U+20AD-20CF,U+2113,U+2C60-2C7F,U+A720-A7FF}
@font-face{font-family:'Lato';font-style:normal;font-weight:400;src:local('Lato Regular'),local(Lato-Regular),url(https://fonts.gstatic.com/s/lato/v14/S6uyw4BMUTPHjx4wXg.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+2000-206F,U+2074,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}
@font-face{font-family:'Lato';font-style:normal;font-weight:700;src:local('Lato Bold'),local(Lato-Bold),url(https://fonts.gstatic.com/s/lato/v14/S6u9w4BMUTPHh6UVSwaPGR_p.woff2) format("woff2");unicode-range:U+0100-024F,U+0259,U+1E00-1EFF,U+2020,U+20A0-20AB,U+20AD-20CF,U+2113,U+2C60-2C7F,U+A720-A7FF}
@font-face{font-family:'Lato';font-style:normal;font-weight:700;src:local('Lato Bold'),local(Lato-Bold),url(https://fonts.gstatic.com/s/lato/v14/S6u9w4BMUTPHh6UVSwiPGQ.woff2) format("woff2");unicode-range:U+0000-00FF,U+0131,U+0152-0153,U+02BB-02BC,U+02C6,U+02DA,U+02DC,U+2000-206F,U+2074,U+20AC,U+2122,U+2191,U+2193,U+2212,U+2215,U+FEFF,U+FFFD}

/*-- Reset CSS --*/
a,abbr,acronym,address,applet,b,big,blockquote,body,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,h1,h2,h3,h4,h5,h6,html,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{padding:0;border:0;outline:0;vertical-align:baseline;background:0 0;text-decoration:none}form,textarea,input,button{-webkit-appearance:none;-moz-appearance:none;appearance:none;border-radius:0}dl,ul{list-style-position:inside;font-weight:400;list-style:none}ul li{list-style:none}caption,th{text-align:center}img{border:none;position:relative}a,a:visited{text-decoration:none}.clearfix{clear:both}.section,.widget,.widget ul{margin:0;padding:0}a{color:$(body.link.color)}a img{border:0}abbr{text-decoration:none}.CSS_LIGHTBOX{z-index:999999!important}.separator a{clear:none!important;float:none!important;margin-left:0!important;margin-right:0!important}#navbar-iframe,.widget-item-control,a.quickedit,.home-link,.feed-links{display:none!important}.center{display:table;margin:0 auto;position:relative}.widget > h2,.widget > h3{display:none}.widget iframe,.widget img{max-width:100%}

/*-- Body Content CSS --*/
html{--body-font:'Lato',Segoe UI,Helvetica Neue,Arial,sans-serif}
body{background:$(body.background);background-color:$(body.background.color);font-family:var(--body-font);font-size:14px;font-weight:400;color:$(body.text.color);word-wrap:break-word;margin:0;padding:0}
#mobile-options{display:none}
#outer-wrapper{overflow:hidden;margin:0 auto;background-color:$(outer.bg);box-shadow:0 0 5px rgba(50,50,50,.05)}
.row-x1{width:$(row.width)}
#content-wrapper{padding:5px;margin:25px auto;overflow:hidden}
#content-wrapper > .container{margin:0 -15px}
#main-wrapper{float:left;overflow:hidden;width:66.66666667%;box-sizing:border-box;padding:0 15px}
#sidebar-wrapper{float:right;overflow:hidden;width:33.33333333%;box-sizing:border-box;padding:0 15px}
.post-link{position:relative;overflow:hidden;display:block;margin:0}
.post-image-wrap{position:relative;display:block}
.post-image,.cmm-avatar,.comments .avatar-image-container{background-color:rgba(155,155,155,0.08);color:transparent!important}
.post-thumb{display:block;position:relative;width:100%;height:100%;background-size:cover;background-position:center;background-repeat:no-repeat;z-index:1;filter:blur(2px);transition:all .17s ease}
.post-thumb.opt-ify{filter:blur(0)}
.post-image:hover .post-thumb,.post-link:hover .post-image .post-thumb{opacity:.85}
.post-title{color:$(post.title.color);transition:color .17s ease}
.post-title a{color:$(post.title.color);display:block;transition:color .17s ease}
.post-link:hover .post-title{color:$(post.title.hover.color)}
.social a:before{display:inline-block;font-family:'Font Awesome 5 Brands';font-style:normal;font-weight:400}
.social .blogger a:before{content:"\f37d"}
.social .facebook a:before{content:"\f09a"}
.social .facebook-f a:before{content:"\f39e"}
.social .twitter a:before{content:"\f099"}
.social .gplus a:before{content:"\f0d5"}
.social .rss a:before{content:"\f09e";font-family:'Font Awesome 5 Free';font-weight:900}
.social .youtube a:before{content:"\f167"}
.social .skype a:before{content:"\f17e"}
.social .stumbleupon a:before{content:"\f1a4"}
.social .tumblr a:before{content:"\f173"}
.social .vk a:before{content:"\f189"}
.social .stack-overflow a:before{content:"\f16c"}
.social .github a:before{content:"\f09b"}
.social .linkedin a:before{content:"\f0e1"}
.social .dribbble a:before{content:"\f17d"}
.social .soundcloud a:before{content:"\f1be"}
.social .behance a:before{content:"\f1b4"}
.social .digg a:before{content:"\f1a6"}
.social .instagram a:before{content:"\f16d"}
.social .pinterest a:before{content:"\f0d2"}
.social .pinterest-p a:before{content:"\f231"}
.social .twitch a:before{content:"\f1e8"}
.social .delicious a:before{content:"\f1a5"}
.social .codepen a:before{content:"\f1cb"}
.social .flipboard a:before{content:"\f44d"}
.social .reddit a:before{content:"\f281"}
.social .whatsapp a:before{content:"\f232"}
.social .messenger a:before{content:"\f39f"}
.social .snapchat a:before{content:"\f2ac"}
.social .email a:before{content:"\f0e0";font-family:'Font Awesome 5 Free'}
.social .external-link a:before{content:"\f35d";font-family:'Font Awesome 5 Free';font-weight:900}
.social-color .blogger a{background-color:#ff5722}
.social-color .facebook a,.social-color .facebook-f a{background-color:#3b5999}
.social-color .twitter a{background-color:#00acee}
.social-color .gplus a{background-color:#db4a39}
.social-color .youtube a{background-color:#f50000}
.social-color .instagram a{background:linear-gradient(15deg,#ffb13d,#dd277b,#4d5ed4)}
.social-color .pinterest a,.social-color .pinterest-p a{background-color:#ca2127}
.social-color .dribbble a{background-color:#ea4c89}
.social-color .linkedin a{background-color:#0077b5}
.social-color .tumblr a{background-color:#365069}
.social-color .twitch a{background-color:#6441a5}
.social-color .rss a{background-color:#ffc200}
.social-color .skype a{background-color:#00aff0}
.social-color .stumbleupon a{background-color:#eb4823}
.social-color .vk a{background-color:#4a76a8}
.social-color .stack-overflow a{background-color:#f48024}
.social-color .github a{background-color:#24292e}
.social-color .soundcloud a{background:linear-gradient(#ff7400,#ff3400)}
.social-color .behance a{background-color:#191919}
.social-color .digg a{background-color:#1b1a19}
.social-color .delicious a{background-color:#0076e8}
.social-color .codepen a{background-color:#000}
.social-color .flipboard a{background-color:#f52828}
.social-color .reddit a{background-color:#ff4500}
.social-color .whatsapp a{background-color:#3fbb50}
.social-color .messenger a{background-color:#0084ff}
.social-color .snapchat a{background-color:#ffe700}
.social-color .email a{background-color:#888}
.social-color .external-link a{background-color:$(button2.bg)}
#header-wrap{position:relative;float:left;width:100%;height:60px}
.header-content{position: relative;float:left;width:100%;height:60px;background-color:$(menu.bg);margin:0;box-shadow:0 0 7px 0 rgba(0,0,0,0.25)}
#header-wrap .container{position:relative;margin:0 auto}
.main-logo{position:relative;float:left;margin:0 20px 0 0}
.header-logo{position:relative;float:left;max-width:250px;height:40px;padding:10px 0}
.header-logo .header-logo-image{float:left;height:40px;overflow:hidden}
.header-logo img{max-width:100%;height:40px;margin:0}
.header-logo h1{font-size:23px;color:$(menu.color);text-transform:uppercase;line-height:40px;margin:0}
.header-logo h1 a{color:$(menu.color)}
.header-logo #h1-tag{position:absolute;top:-9000px;left:-9000px;display:none;visibility:hidden}
.header-menu{position:static;float:left;height:60px;margin:0}
#speedify-main-menu .widget,#speedify-main-menu .widget > .widget-title{display:none}
#speedify-main-menu .show-menu{display:block}
#speedify-main-menu{position:static;width:100%;height:60px;z-index:10}
#speedify-main-menu ul > li{position:relative;float:left;display:inline-block;padding:0;margin:0;transition:background .17s ease}
#speedify-main-menu ul > li > a{position:relative;display:block;height:60px;color:$(menu.color);font-size:15px;font-weight:700;line-height:60px;padding:0 15px;margin:0;transition:color .17s}
#speedify-main-menu ul > li:hover > a{color:$(menu.hover.color)}
#speedify-main-menu ul > li > ul{position:absolute;float:left;left:0;top:60px;width:180px;background-color:$(sub.menu.bg);z-index:99999;padding:3px 0;box-shadow:0 2px 3px 0 rgba(0,0,0,0.07);visibility:hidden;opacity:0;-webkit-transform:translateY(-10px);-moz-transform:translateY(-10px);transform:translateY(-10px)}
#speedify-main-menu ul > li > ul > li > ul{position:absolute;float:left;top:0;left:100%;-webkit-transform:translateX(-10px);-moz-transform:translateX(-10px);transform:translateX(-10px)}
#speedify-main-menu ul > li > ul > li{display:block;float:none;position:relative}
#speedify-main-menu ul > li > ul > li a{display:block;height:33px;font-size:14px;color:$(sub.menu.color);line-height:33px;box-sizing:border-box;padding:0 15px;margin:2px 0;transition:color .17s}
#speedify-main-menu ul > li > ul > li:hover > a{color:$(sub.menu.hover.color)}
#speedify-main-menu ul > li.has-sub > a:after{content:'\f078';float:right;font-family:'Font Awesome 5 Free';font-size:9px;font-weight:900;margin:0 0 0 5px}
#speedify-main-menu ul > li > ul > li.has-sub > a:after{content:'\f054';float:right;margin:0}
#speedify-main-menu ul > li:hover > ul,#speedify-main-menu ul > li > ul > li:hover > ul{visibility:visible;opacity:1;-webkit-backface-visibility:hidden;-webkit-transform:translate(0);-moz-transform:translate(0);transform:translate(0)}
#speedify-main-menu ul ul{transition:all .17s ease}
#speedify-main-menu .getMega{display:none}
#speedify-main-menu .mega-menu{position:static!important}
#speedify-main-menu .mega-menu > ul{width:100%;box-sizing:border-box;padding:20px 10px}
#speedify-main-menu .mega-menu > ul.mega-widget,#speedify-main-menu .mega-menu > ul.complex-tabs{overflow:hidden}
#speedify-main-menu .mega-menu > ul.complex-tabs > ul.select-tab{position:relative;float:left;width:20%;box-sizing:border-box;padding:20px 0;margin:-20px 0 0 -10px}
#speedify-main-menu .mega-menu > ul.complex-tabs > ul.select-tab:before{content:'';position:absolute;left:0;top:0;width:100%;height:100vh;box-sizing:border-box;display:block;border-right:1px solid rgba(155,155,155,0.17)}
#speedify-main-menu .mega-menu > ul.complex-tabs > ul.select-tab > li{width:100%;margin:0;transition:background .17s ease}
#speedify-main-menu ul > li > ul.complex-tabs > ul.select-tab > li > a{display:block;height:33px;font-size:14px;color:$(sub.menu.color);line-height:33px;padding:0 20px}
#speedify-main-menu .mega-menu > ul.complex-tabs > ul.select-tab > li.active > a:after{content:'\f054';font-family:'Font Awesome 5 Free';font-weight:900;font-size:9px;float:right}
#speedify-main-menu .mega-menu > ul.complex-tabs > ul.select-tab > li.active > a,#speedify-main-menu .mega-menu > ul.complex-tabs > ul.select-tab > li:hover > a{color:$(sub.menu.hover.color)}
.mega-tab{display:none;position:relative;width:80%;float:right}
.tab-active{display:block}
.tab-animated{-webkit-animation-duration:.5s;animation-duration:.5s;-webkit-animation-fill-mode:both;animation-fill-mode:both}
@keyframes tab-fadeIn {
from{opacity:0}
to{opacity:1}
}
.tab-fadeIn{animation-name:tab-fadeIn}
@keyframes tab-fadeInUp {
from{opacity:0;transform:translate3d(0,5px,0)}
to{opacity:1;transform:translate3d(0,0,0)}
}
.tab-fadeInUp{animation-name:tab-fadeInUp}
.mega-widget .mega-item{float:left;width:20%;box-sizing:border-box;padding:0 10px}
.mega-tab .mega-widget .mega-item{width:25%}
.mega-widget .mega-content{position:relative;width:100%;overflow:hidden;padding:0}
.mega-content .post-image{width:100%;height:120px;background-color:rgba(255,255,255,0.01);z-index:1;display:block;position:relative;overflow:hidden;padding:0}
.mega-content .post-title{position:relative;font-size:14px;color:$(sub.menu.color);font-weight:700;line-height:1.4em;margin:7px 0 5px;padding:0}
.mega-content .post-link:hover .post-title{color:$(sub.menu.post.title.hover.color)}
.mega-content .post-meta,.mega-content .post-meta span:before{font-size:11px}
.mega-menu .no-posts{display:block;height:60px;color:$(meta.color);text-align:center;line-height:60px}
.show-search,.hide-search{position:absolute;top:0;right:0;display:block;width:25px;height:60px;color:$(menu.color);font-size:14px;line-height:60px;text-align:right;cursor:pointer;z-index:20;transition:color .17s ease}
.show-search:before{content:"\f002";font-family:'Font Awesome 5 Free';font-weight:900}
.hide-search:before{content:"\f00d";font-family:'Font Awesome 5 Free';font-weight:900}
.show-search:hover,.hide-search:hover{color:$(menu.hover.color)}
#nav-search{display:none;position:absolute;left:0;top:0;width:100%;height:60px;z-index:25;background-color:$(menu.bg);box-sizing:border-box;padding:0}
#nav-search .search-form{width:100%;height:60px;background-color:rgba(0,0,0,0);line-height:60px;overflow:hidden;padding:0}
#nav-search .search-input{width:100%;height:60px;color:$(menu.color);margin:0;padding:0 60px 0 0;background-color:rgba(0,0,0,0);font-family:inherit;font-size:13px;font-weight:400;box-sizing:border-box;border:0}
#nav-search .search-input:focus{color:$(menu.color);outline:none}
#nav-search .search-input::placeholder{color:$(menu.color);opacity:.5}
.overlay{display:none;visibility:hidden;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.7);z-index:1000;margin:0}
.show-mobile-menu{display:none;position:absolute;top:0;left:0;height:60px;color:$(menu.color);font-size:16px;font-weight:700;line-height:60px;text-align:center;cursor:pointer;z-index:20;padding:0 20px;transition:color .17s ease}
.show-mobile-menu:before{content:"\f0c9";font-family:'Font Awesome 5 Free';font-weight:900}
.show-mobile-menu:hover{color:$(menu.hover.color)}
.slide-menu{display:none;position:fixed;width:300px;max-height:100%;overflow:auto;top:0;left:0;bottom:0;background-color:$(mobile.menu.bg);z-index:1010;transform:translateX(-100%);visibility:hidden;box-shadow:3px 0 7px rgba(0,0,0,0.1);transition:all .17s ease}
.nav-active .slide-menu{transform:translateX(0px);visibility:visible}
.slide-menu-header{float:left;width:100%;height:40px;overflow:hidden;border-bottom:1px solid rgba(155,155,155,0.05)}
.social-mobile{display:block;padding:0 20px}
.social-mobile ul{font-size:14px;line-height:40px;z-index:15;margin:0}
.social-mobile ul li{display:inline-block;margin:0 5px 0 0}
.social-mobile ul li a{display:block;color:$(mobile.menu.color);padding:0 5px;transition:color .17s ease}
.social-mobile ul li:first-child a{padding-left:0}
.social-mobile ul li a:hover{color:$(mobile.menu.hover.color)}
.hide-mobile-menu{position:absolute;top:0;right:0;display:block;width:40px;height:40px;color:$(mobile.menu.color);font-size:16px;line-height:40px;text-align:center;cursor:pointer;z-index:20;transition:color .17s ease}
.hide-mobile-menu:before{content:"\f00d";font-family:'Font Awesome 5 Free';font-weight:900}
.hide-mobile-menu:hover{color:$(mobile.menu.hover.color)}
.mobile-menu{position:relative;float:left;width:100%;box-sizing:border-box;padding:20px}
.mobile-menu > ul{margin:0}
.mobile-menu .m-sub{display:none;padding:0}
.mobile-menu ul li{position:relative;display:block;overflow:hidden;float:left;width:100%;font-size:16px;font-weight:700;line-height:40px;margin:0;padding:0;border-top:1px solid rgba(155,155,155,0.03)}
.mobile-menu > ul li ul{overflow:hidden}
.mobile-menu > ul > li:first-child{border-top:0}
.mobile-menu > ul > li:last-child{border-bottom:1px solid rgba(0,0,0,0.02)}
.mobile-menu ul li a{color:$(mobile.menu.color);padding:0;display:block;transition:color .17s ease}
.mobile-menu ul li.has-sub .submenu-toggle{position:absolute;top:0;right:0;color:$(mobile.menu.color);cursor:pointer}
.mobile-menu ul li.has-sub .submenu-toggle:after{content:'\f054';font-family:'Font Awesome 5 Free';font-weight:900;float:right;width:40px;font-size:12px;text-align:center;transition:all .17s ease}
.mobile-menu ul li.has-sub.show > .submenu-toggle:after{transform:rotate(90deg)}
.mobile-menu ul li a:hover,.mobile-menu ul li.has-sub.show > a,.mobile-menu ul li.has-sub.show > .submenu-toggle{color:$(mobile.menu.hover.color)}
.mobile-menu > ul > li > ul > li a{font-size:14px;opacity:.8;padding:0 0 0 15px}
.mobile-menu > ul > li > ul > li > ul > li > a{padding:0 0 0 30px}
.mobile-menu ul > li > .submenu-toggle:hover{color:$(mobile.menu.hover.color)}
.fixed-menu{position:fixed;top:-60px;left:0;width:100%;z-index:990;transition:top .25s ease}
.show-fixed-menu{top:0}
.nav-active .fixed-menu{top:0}
.header-content.fixed-menu,.fixed-menu .header-menu,.fixed-menu #speedify-main-menu,.fixed-menu #nav-search,.fixed-menu #nav-search .search-input{height:50px}
.fixed-menu .header-logo{padding:5px 0}
.fixed-menu ul#speedify-main-menu-nav > li > a,.fixed-menu #nav-search .search-form,.fixed-menu .show-search,.fixed-menu .hide-search,.fixed-menu .show-mobile-menu{height:50px;line-height:50px}
.fixed-menu #speedify-main-menu-nav > li > ul{top:50px}
.loader{position:relative;overflow:hidden;display:block}
.loader:after{content:'';position:absolute;top:50%;left:50%;width:26px;height:26px;margin:-16px 0 0 -16px;border:3px solid rgba(155,155,155,0.17);border-right-color:$(main.color);border-radius:100%;animation:spinner .8s infinite linear;transform-origin:center}
@-webkit-keyframes spinner {
0%{-webkit-transform:rotate(0deg);transform:rotate(0deg)}
to{-webkit-transform:rotate(1turn);transform:rotate(1turn)}
}
@keyframes spinner {
0%{-webkit-transform:rotate(0deg);transform:rotate(0deg)}
to{-webkit-transform:rotate(1turn);transform:rotate(1turn)}
}
#featured-section .widget-title{display:none}
.featured-section .FeaturedPost .post{position:relative;overflow:hidden;background-color:$(posts.background.color);padding:25px;margin:0 0 25px;box-shadow:0 0 3px rgba(0,0,0,0.05)}
.FeaturedPost .post-image-wrap{float:left;width:100%;height:300px;overflow:hidden;margin:0 0 10px}
.FeaturedPost .post-image{width:100%;height:100%;position:relative;display:block;z-index:1;overflow:hidden}
.FeaturedPost .post-header{float:left;margin:0}
.FeaturedPost .post-title{font-size:27px;font-weight:700;line-height:1.4em;text-decoration:none;margin:0 0 10px}
.FeaturedPost .post-title a:hover{color:$(link.hover.color)}
.FeaturedPost .post-content{float:left;margin:10px 0 0}
#custom-ads,#ad-top,#ad-footer{display:none;float:left;width:100%;margin:0}
#main-ads1{float:left;width:100%;margin:0}
.main-ads .widget > .widget-title > h3,#ad-top .widget > .widget-title > h3,#ad-footer .widget > .widget-title > h3{height:auto;font-size:10px;color:$(meta.color);font-weight:400;text-transform:inherit;margin:0 0 5px}
.main-ads .widget,#ad-top .widget,#ad-footer .widget{width:728px;max-width:100%;margin:25px auto 0}
.main-ads .widget{margin:0 auto}
#ad-footer .widget{margin:0 auto 25px}
.main-ads .widget .widget-content,#ad-top .widget-content,#ad-footer .widget-content{position:relative;width:100%;max-height:90px;overflow:hidden;line-height:1}
.main-ads .widget .widget-content{margin:0 0 25px}
#main-wrapper #main{float:left;width:100%;background-color:$(posts.background.color);box-shadow:0 0 3px rgba(0,0,0,0.05)}
.queryMessage{overflow:hidden;color:$(link.color);font-size:13px;padding:10px 25px;border-bottom:1px solid rgba(155,155,155,0.17)}
.queryMessage .query-info{margin:0}
.queryMessage .search-query,.queryMessage .search-label{font-weight:700;text-transform:uppercase}
.queryMessage .search-query:before,.queryMessage .search-label:before{content:"\201c"}
.queryMessage .search-query:after,.queryMessage .search-label:after{content:"\201d"}
.queryMessage a.show-more{float:right;color:$(main.color);transition:opacity .17s}
.queryMessage a.show-more:hover{text-decoration:underline;opacity:.8}
.queryEmpty{font-size:13px;font-weight:400;padding:0 25px;margin:35px 0 0;text-align:center}
.blog-post{display:block;overflow:hidden;word-wrap:break-word}
.index-post-wrap{padding:20px 25px 25px}
.index-post{margin:35px 0 0}
.index-post.post-0{margin:0}
.index-post .post-image-wrap{float:left;width:270px;height:175px;margin:0 20px 0 0}
.index-post .post-image-wrap .post-image{width:100%;height:100%;position:relative;display:block;z-index:1;overflow:hidden}
.index-post .post-header{overflow:hidden;margin:0 0 18px}
.index-post .post-header .post-title{font-size:27px;font-weight:700;line-height:1.4em;margin:0 0 12px}
.index-post .post-header .post-title:hover a{color:$(link.hover.color)}
.post-meta{font-size:13px;color:$(meta.color);font-weight:400;padding:0 1px}
.post-meta span{float:left;margin:0 10px 0 0}
.post-meta a{color:$(meta.color);transition:color .17s ease}
.post-meta a:hover{color:$(link.hover.color)}
.post-meta span:before{font-family:'Font Awesome 5 Free';font-size:12px;font-weight:400;margin:0 3px 0 0}
.post-meta .post-author:before{content:'\f007'}
.post-meta .post-date:before{content:'\f017'}
.post-meta .post-tag:before{content:'\f292';font-weight:700}
.post-meta .post-replies:before{content:'\f086'}
.index-post .post-content{overflow:hidden}
.post-snippet{position:relative;display:block;overflow:hidden;font-size:15px;color:$(post.snip.color);line-height:1.6em;font-weight:400;margin:0}
a.read-more{display:inline-block;font-size:15px;color:$(post.title.hover.color);margin:10px 0 0;transition:color .17s ease}
a.read-more:hover{color:$(post.title.color)}
.item-post-inner{position:relative;float:left;width:100%;overflow:hidden;box-sizing:border-box;padding:0 25px}
.item-post .blog-post-header{position:relative;float:left;width:100%;overflow:hidden;padding:15px 0 0}
.item-post h1.post-title{font-size:29px;line-height:1.4em;font-weight:700;position:relative;display:block;margin:0 0 13px}
.static_page .item-post h1.post-title{margin:0}
.item-post .post-body{position:relative;float:left;width:100%;overflow:hidden;font-size:15px;color:$(post.text.color);line-height:1.6em;padding:25px 0}
.item-post .post-body img{max-width:100%}
.post-body h1,.post-body h2,.post-body h3,.post-body h4{font-size:18px;font-weight:700;margin:0 0 15px}
.post-body h1,.post-body h2{font-size:23px}
.post-body h3{font-size:21px}
blockquote{background-color:rgba(155,155,155,0.08);font-style:italic;padding:15px 25px;margin:0;border-left:3px solid $(main.color)}
blockquote:before,blockquote:after{display:inline-block;font-family:'Font Awesome 5 Free';font-style:normal;font-weight:900;color:#aaa;line-height:1}
blockquote:before{content:'\f10d';margin:0 10px 0 0}
blockquote:after{content:'\f10e';margin:0 0 0 10px}
.post-body ul,.widget .post-body ol{line-height:1.5;font-weight:400;padding:0 0 0 30px;margin:10px 0}
.post-body li{margin:5px 0;padding:0;line-height:1.5}
.post-body ul li{list-style:disc inside}
.post-body ol li{list-style:decimal inside}
.post-body u{text-decoration:underline}
.post-body strike{text-decoration:line-through}
.post-body a{color:$(body.link.color)}
.post-body a:hover{text-decoration:underline}
.post-body a.button{display:inline-block;height:30px;background-color:$(button1.bg);font-size:13px;color:$(button1.color);font-weight:700;line-height:30px;text-align:center;text-decoration:none;cursor:pointer;padding:0 15px;margin:0 5px 5px 0;border-radius:2px;transition:all .17s ease}
.post-body a.colored-button{color:#fff}
.post-body a.button:hover{background-color:$(button2.bg);color:$(button2.color)}
.post-body a.colored-button:hover{background-color:$(button2.bg)!important;color:$(button2.color)!important}
.button:before{font-family:'Font Awesome 5 Free';font-weight:900;display:inline-block;margin:0 5px 0 0}
.button.preview:before{content:"\f06e"}
.button.download:before{content:"\f019"}
.button.link:before{content:"\f0c1"}
.button.cart:before{content:"\f07a"}
.button.info:before{content:"\f06a"}
.button.share:before{content:"\f1e0"}
.alert-message{position:relative;display:block;color:#fff;padding:15px;border-radius:2px}
.alert-message.alert-success{background-color:#3ed37c}
.alert-message.alert-info{background-color:#3799dc}
.alert-message.alert-warning{background-color:#b98b3d}
.alert-message.alert-error{background-color:#e74c3c}
.alert-message:before{font-family:'Font Awesome 5 Free';font-size:16px;font-weight:900;display:inline-block;margin:0 5px 0 0}
.alert-message.alert-success:before{content:"\f058"}
.alert-message.alert-info:before{content:"\f05a"}
.alert-message.alert-warning:before{content:"\f06a"}
.alert-message.alert-error:before{content:"\f057"}
.contact-form{overflow:hidden}
.contact-form .widget-title{display:none}
.contact-form .contact-form-name{width:calc(50% - 5px)}
.contact-form .contact-form-email{width:calc(50% - 5px);float:right}
.code-box{position:relative;display:block;background-color:rgba(155,155,155,0.1);font-family:Monospace;font-size:13px;white-space:pre-wrap;line-height:1.4em;padding:10px;border:1px solid rgba(155,155,155,0.3);border-radius:2px}
.post-labels{overflow:hidden;float:left;width:100%;height:auto;position:relative;margin:0 0 25px}
.post-labels span,.post-labels a{float:left;height:22px;background-color:$(button3.bg);font-size:12px;color:$(button3.color);line-height:22px;font-weight:400;padding:0 7px;margin:0 5px 0 0;border-radius:2px;transition:all .17s ease}
.post-labels span{background-color:$(button2.bg);color:$(button2.color);font-weight:700}
.post-labels a:hover{background-color:$(button1.bg);color:$(button1.color)}
.post-share{position:relative;float:left;width:100%;overflow:hidden;margin:0 0 25px}
.post-header .post-share{margin:20px 0 0}
ul.share-links{position:relative}
.share-links li{float:left;overflow:hidden;margin:0 5px 0 0}
.share-links li a,.share-links li span{display:block;cursor:pointer;width:44px;height:30px;line-height:30px;color:#fff;font-size:14px;font-weight:400;text-align:center;border-radius:2px;transition:all .17s ease}
.share-links li span{position:relative;color:$(post.title.color);line-height:28px;box-sizing:border-box;margin:0 5px 0 0;border:1px solid rgba(155,155,155,0.17)}
.share-links li span:before{content:'\f1e0';font-family:'Font Awesome 5 Free';font-weight:900}
.share-links li span:after{content:'';position:absolute;width:6px;height:6px;top:10px;right:-4px;background-color:$(posts.background.color);border:1px solid rgba(155,155,155,0.17);border-left-color:rgba(0,0,0,0);border-bottom-color:rgba(0,0,0,0);transform:rotate(45deg)}
.share-links li.whatsapp-mobile{display:none}
.mobile-share li.whatsapp-desktop{display:none}
.mobile-share li.whatsapp-mobile{display:inline-block}
.share-links li a:hover{opacity:.8}
.share-links .show-hid a{background-color:rgba(155,155,155,0.1);font-size:14px;color:#888}
.share-links .show-hid a:before{content:'\f067';font-family:'Font Awesome 5 Free';font-weight:900}
.show-hidden .show-hid a:before{content:'\f068'}
.share-links li.linkedin,.share-links li.email{display:none}
.show-hidden li.pinterest-p,.show-hidden li.linkedin,.show-hidden li.email{display:inline-block}
.post-footer{position:relative;float:left;width:100%}
.about-author{position:relative;float:left;width:100%;overflow:hidden;background-color:$(author.box.bg);box-sizing:border-box;padding:20px;margin:0 0 25px}
.about-author .avatar-container{position:relative;float:left;width:80px;height:80px;background-color:rgba(155,155,155,0.06);overflow:hidden;margin:0 17px 0 0;border-radius:2px}
.about-author .author-avatar{float:left;width:100%;height:100%;background-size:cover;background-position:center;background-repeat:no-repeat}
.author-name{display:block;font-size:16px;font-weight:700;line-height:16px;margin:0 0 5px}
.author-name span{color:$(author.title)}
.author-name a{color:$(author.title);transition:color .17s ease}
.author-name a:hover{color:$(author.title.hover.color)}
.author-description{overflow:hidden}
.author-description span{display:block;overflow:hidden;font-size:13px;color:$(author.text.color);font-weight:400;line-height:1.5em}
.author-description span br{display:none}
.author-description a{display:none;float:left;width:20px;height:20px;color:#fff;font-size:13px;text-align:center;line-height:20px;margin:7px 10px 0 0;border-radius:2px;transition:opacity .17s ease}
.author-description a:hover{opacity:.8}
.author-description.show-icons li,.author-description.show-icons a{display:inline-block}
#related-wrap{overflow:hidden;float:left;width:100%;box-sizing:border-box;padding:0 25px;margin:0 0 25px}
.related-title h3{color:$(post.title.color);font-size:17px;font-weight:700;margin:0 0 15px}
#related-wrap .related-tag{display:none}
.related-content{float:left;width:100%}
.related-content .loader{height:200px}
.related-posts{position:relative;overflow:hidden;display:flex;margin:0 -10px;padding:0}
.related-posts .related-item{width:calc(100% / 3);position:relative;overflow:hidden;float:left;display:flex;box-sizing:border-box;margin:0;padding:0 10px}
.related-posts .related-item-inner{position:relative;width:100%;display:block}
.related-posts .post-image-wrap{position:relative;overflow:hidden}
.related-posts .post-image{width:100%;height:125px;position:relative;overflow:hidden;display:block}
.related-posts .post-header{display:block;overflow:hidden;margin:7px 0 0}
.related-posts .post-title{font-size:14px;font-weight:700;line-height:1.4em;display:block;margin:0 0 5px}
.related-posts .post-meta{font-size:11px;margin:0}
.related-posts .post-meta span:before{font-size:11px}
.post-nav{position:relative;float:left;width:100%;overflow:hidden;font-size:13px;box-sizing:border-box;margin:0 0 25px}
.post-nav a{color:#aaa;transition:color .17s ease}
.post-nav a:hover{color:$(link.hover.color);text-decoration:underline}
.post-nav span{color:#aaa;opacity:.7}
.post-nav .blog-pager-newer-link:before,.post-nav .blog-pager-older-link:after{margin-top:4px}
#blog-pager{float:left;width:100%;font-size:14px;font-weight:700;clear:both;box-sizing:border-box;padding:0 25px;margin:10px 0 25px}
.blog-pager .blog-pager-newer-link,.blog-pager .blog-pager-older-link{background-color:$(button2.bg);min-width:30px;height:30px;color:$(button2.color);font-size:14px;line-height:30px;box-sizing:border-box;padding:0 10px;margin:0 5px 0 0;border-radius:2px;transition:all .17s ease}
.blog-pager .page-num{float:left;background-color:$(button2.bg);min-width:30px;height:30px;color:$(button2.color);text-align:center;line-height:30px;box-sizing:border-box;padding:0 10px;margin:0 5px 0 0;border-radius:2px;transition:all .17s ease}
.blog-pager .page-prev,.blog-pager .page-next{font-size:10px}
.blog-pager .page-prev:before,.blog-pager .page-next:before{font-family:'Font Awesome 5 Free';font-weight:900}
.blog-pager .page-prev:before{content:'\f053'}
.blog-pager .page-next:before{content:'\f054'}
.blog-pager a:hover{background-color:$(button1.bg);color:$(button1.color)}
.blog-pager .page-active{background-color:$(button1.bg);color:$(button1.color)}
.blog-pager .page-dots{min-width:auto;background-color:rgba(0,0,0,0);color:$(link.color);padding:0 5px;border:0}
.archive .blog-pager{display:none}
.home .blog-pager .blog-pager-newer-link,.home .blog-pager .blog-pager-older-link{display:none}
.blog-pager-newer-link{float:left}
.blog-pager-older-link{float:right}
.blog-pager-newer-link:before{content:'\f053';float:left;font-family:'Font Awesome 5 Free';font-size:9px;font-weight:900;margin:1px 4px 0 0}
.blog-pager-older-link:after{content:'\f054';float:right;font-family:'Font Awesome 5 Free';font-size:9px;font-weight:900;margin:1px 0 0 4px}
.speedify-blog-post-comments{display:none;float:left;width:100%;margin:0}
#comments,#disqus_thread,.fb-comments{float:left;width:100%;box-sizing:border-box;padding:15px 25px 25px}
#disqus_thread,.fb-comments{padding:10px 25px}
#gpluscomments{float:left!important;width:100%!important;height:auto!important;background-color:$(posts.background.color)!important;box-sizing:border-box!important;padding:25px!important;margin:0important}
#gpluscomments iframe{float:left!important;width:100%}
.comments{display:block;clear:both;margin:0}
.comments > h3{position:relative;color:$(post.title.color);font-size:17px;font-weight:700;padding:0 0 15px;margin:0 0 15px;border-bottom:1px dashed rgba(155,155,155,.51)}
.comments.no-comments > h3{padding:0;margin:0 0 15px;border:0}
.comments .comments-content{float:left;width:100%;margin:0}
#comments h4#comment-post-message{display:none}
.comments .comment-block{padding:0 0 0 50px}
.comments .comment-content{font-size:13px;line-height:1.6em;margin:7px 0}
.comment-thread .comment{position:relative;padding:15px 0 0;margin:15px 0 0;list-style:none;border-top:1px dashed rgba(155,155,155,.51)}
.comment-thread ol{padding:0;margin:0 0 15px}
.comment-thread ol > li:first-child{padding:0;margin:0;border:0}
.comment-thread .avatar-image-container{position:absolute;top:15px;left:0;width:35px;height:35px;border-radius:100%;overflow:hidden}
.comment-thread ol > li:first-child > .avatar-image-container{top:0}
.avatar-image-container img{width:100%;height:100%;border-radius:100%}
.comments .comment-header .user{font-size:16px;color:$(post.title.color);display:inline-block;font-style:normal;font-weight:700;margin:0}
.comments .comment-header .user a{color:$(post.title.color);transition:color .17s ease}
.comments .comment-header .user a:hover{color:$(post.title.hover.color)}
.comments .comment-header .icon.user{display:none}
.comments .comment-header .icon.blog-author{display:inline-block;font-size:12px;color:$(main.color);font-weight:400;vertical-align:top;margin:0 0 0 5px}
.comments .comment-header .icon.blog-author:before{content:'\f058';font-family:'Font Awesome 5 Free';font-weight:400}
.comments .comment-header .datetime{float:right;display:block}
.comment-header .datetime a{font-size:11px;color:$(meta.color)}
.comments .comment-actions{display:block;margin:0 0 15px}
.comments .comment-actions a{color:$(meta.color);font-size:12px;font-style:italic;margin:0 15px 0 0;transition:color .17s ease}
.comments .comment-actions a:hover{color:$(link.hover.color);text-decoration:underline}
.item-control{display:none}
.loadmore.loaded a{display:inline-block;border-bottom:1px solid rgba(155,155,155,.51);text-decoration:none;margin-top:15px}
.comments .continue{display:none!important}
.comments .comment-replies{padding:0 0 0 55px}
.thread-expanded .thread-count a,.loadmore{display:none}
.comments .footer,.comments .comment-footer{float:left;width:100%;font-size:13px;margin:0}
.comment-form{float:left;width:100%;margin:10px 0 0}
.comment-form > p{font-size:13px;padding:10px 8px 5px;margin:0}
.comment-form > p > a{color:$(main.color)}
.comment-form > p > a:hover{text-decoration:underline}
#sidebar-wrapper .sidebar{float:left;width:100%}
.sidebar > .widget{position:relative;float:left;width:100%;margin:0 0 25px;box-shadow:0 0 3px rgba(0,0,0,0.05)}
#sidebar-2 > .widget:last-child{margin:0}
.sidebar .widget-content{float:left;width:100%;background-color:$(sidebar.widget.bg);box-sizing:border-box;padding:15px}
.sidebar .no-style .widget-content{background-color:rgba(0,0,0,0);padding:0;box-shadow:none}
.sidebar .widget > .widget-title{position:relative;float:left;width:100%;margin:0}
.sidebar .widget > .widget-title > h3{position:relative;height:30px;background-color:$(sidebar.title.bg);font-size:15px;color:$(sidebar.title.color);line-height:30px;font-weight:700;padding:0 15px;margin:0}
.sidebar .no-style > .widget-title{display:none}
ul.social-counter{display:flex;flex-wrap:wrap;margin:0}
.social-counter li{float:left;width:calc(25% - 30px / 4);display:flex;flex-direction:column;margin:10px 0 0 10px}
.social-counter li:nth-child(4n+1){margin:10px 0 0}
.social-counter li:nth-child(1){margin:0}
.social-counter li:nth-child(2),.social-counter li:nth-child(3),.social-counter li:nth-child(4){margin:0 0 0 10px}
.social-counter li a{display:block;height:100%;height:40px;font-size:22px;color:#fff;text-align:center;line-height:40px;padding:0 10px;border-radius:2px;transition:opacity .17s ease}
.social-counter li a:hover{opacity:.8}
.sidebar .loader{height:180px}
#speedify-sidebar-tabs{display:none;position:relative;background-color:$(sidebar.widget.bg);box-sizing:border-box;padding:0;margin:0 0 25px}
.speedify-sidebar-tabs .select-tab{position:relative;width:100%;height:30px;background-color:$(sidebar.title.bg);overflow:hidden;margin:0}
.speedify-sidebar-tabs .select-tab li{position:relative;float:left;display:inline-block;width:100%;height:30px;font-size:15px;color:$(sidebar.title.color);font-weight:700;line-height:30px;text-align:center;cursor:pointer;list-style:none;margin:0;padding:0;transition:background .17s}
.tabs-1 .select-tab li{position:relative;float:left;width:auto}
.tabs-1 .select-tab li,.tabs-1 .select-tab li a{cursor:auto}
.tabs-2 .select-tab li{width:50%}
.tabs-3 .select-tab li{width:calc(100% / 3)}
.tabs-4 .select-tab li{width:25%;font-size:10px}
.speedify-sidebar-tabs .select-tab li > a{color:$(sidebar.title.color);display:block;padding:0 15px}
.tabs-3 .select-tab li a{padding:0 10px}
.tabs-4 .select-tab li a{padding:0 5px}
.speedify-sidebar-tabs .select-tab li.active,.speedify-sidebar-tabs .select-tab li.active:hover{background-color:rgba(155,155,155,0.06)}
.speedify-sidebar-tabs .select-tab li:hover{background-color:rgba(155,155,155,0.06)}
.speedify-sidebar-tabs .widget{display:none}
.speedify-sidebar-tabs .tab-active{display:block}
.speedify-sidebar-tabs .widget{margin:0}
.speedify-sidebar-tabs > .widget > .widget-title{display:none}
.custom-widget .custom-item{display:block;overflow:hidden;margin:0 0 15px}
.custom-widget .custom-item:last-child{margin:0}
.custom-widget .post-image{position:relative;float:left;width:80px;height:65px;overflow:hidden;margin:0 10px 0 0}
.custom-widget .cmm-avatar{width:55px;height:55px;margin:0 10px 0 0}
.custom-widget .cmm-snippet{display:block;font-size:12px;color:#888;line-height:1.4em;margin:2px 0 0}
.custom-widget .post-header{overflow:hidden}
.custom-widget .post-title{font-size:14px;font-weight:700;line-height:1.4em;margin:0}
.custom-widget .post-meta{font-size:11px;margin:5px 0 0}
.custom-widget .post-meta span:before{font-size:11px}
ul.insta-widget{position:relative;margin:0 -2px}
.insta-widget li{float:left;width:calc(100% / 3);height:85px;box-sizing:border-box;padding:0 2px;margin:4px 0 0}
.insta-widget .item-0,.insta-widget .item-1,.insta-widget .item-2{margin:0}
.insta-widget .insta-image{position:relative;display:block;width:100%;height:100%;overflow:hidden;background-color:rgba(155,155,155,0.08)}
.insta-widget .insta-image:before{content:'';position:absolute;top:0;left:0;width:100%;height:100%;background-color:rgba(0,0,0,0.2);z-index:15;opacity:0;transition:opacity .17s ease}
.insta-widget .insta-image:after{content:"\f16d";font-family:'Font Awesome 5 Brands';display:block;position:absolute;top:calc(50% - 13px);left:calc(50% - 13px);color:#fff;height:26px;font-size:24px;width:26px;font-weight:400;text-align:center;line-height:26px;z-index:20;opacity:0;transition:opacity .17s ease}
.insta-widget .insta-image:hover:before,.insta-widget .insta-image:hover:after{opacity:1}
.insta-widget .insta-image .insta-thumb{display:block;width:100%;height:100%;background-size:cover;background-position:center;background-repeat:no-repeat;z-index:10}
.PopularPosts .popular-post{display:block;overflow:hidden;margin:0 0 15px}
.PopularPosts .popular-post:last-child{margin:0}
.PopularPosts .post-image-wrap{float:left;width:80px;height:65px;overflow:hidden;margin:0 10px 0 0}
.PopularPosts .post-image{width:100%;height:100%;position:relative;display:block;z-index:1;overflow:hidden}
.PopularPosts .post-header{overflow:hidden}
.PopularPosts .post-title{font-size:14px;font-weight:700;line-height:1.4em;margin:0}
.PopularPosts .post-meta{font-size:11px;margin:5px 0 0}
.PopularPosts .post-meta span:before{font-size:11px}
.speedify-widget-ready .FeaturedPost .post-image-wrap{height:170px;margin:0 0 10px}
.speedify-widget-ready .FeaturedPost .post-title{font-size:15px;margin:0 0 7px}
.FollowByEmail .widget-content{position:relative;text-align:center;box-sizing:border-box;padding:0}
.FollowByEmail .widget-content-inner{padding:20px}
.FollowByEmail .fbm-ify .widget-content-inner{position:relative;overflow:hidden;background-size:cover;background-repeat:no-repeat}
.FollowByEmail .fbm-ify .widget-content-inner:before{content:'';left:0;right:0;top:0;bottom:0;background-color:rgba(10,10,10,0.75);z-index:1;position:absolute}
.follow-by-email-content{position:relative;z-index:5}
.follow-by-email-title{font-size:17px;color:$(link.color);font-weight:700;text-transform:uppercase;margin:0 0 10px}
.fbm-ify .follow-by-email-title{color:#fff}
.follow-by-email-text{font-size:14px;line-height:1.5em;margin:0 0 15px}
.fbm-ify .follow-by-email-text{color:#ccc}
.follow-by-email-address{width:100%;height:32px;background-color:#fff;font-family:inherit;font-size:12px;text-align:center;box-sizing:border-box;padding:0 10px;margin:0 0 10px;border:1px solid rgba(155,155,155,0.17)}
.follow-by-email-submit{width:100%;height:32px;background-color:$(button1.bg);font-family:inherit;font-size:11px;color:$(button1.color);font-weight:700;line-height:33px;text-transform:uppercase;cursor:pointer;padding:0 20px;border:0;transition:all .17s ease}
.follow-by-email-submit:hover{background-color:$(button2.bg);color:$(button2.color)}
.list-label li,.archive-list li{position:relative;display:block}
.list-label li a,.archive-list li a{display:block;color:$(link.color);font-size:12px;font-weight:400;text-transform:capitalize;padding:8px 0;border-top:1px dashed rgba(155,155,155,0.17);transition:color .17s}
.list-label li:first-child a,.archive-list li:first-child a{padding:0 0 8px;border:0}
.list-label li:last-child a,.archive-list li:last-child a{padding-bottom:0}
.list-label li a:before,.archive-list li a:before{content:'\f054';float:left;color:$(link.color);font-weight:900;font-family:'Font Awesome 5 Free';font-size:8px;margin:2px 3px 0 0;transition:color .17s}
.list-label li a:hover,.archive-list li a:hover{color:$(link.hover.color)}
.list-label .label-count,.archive-list .archive-count{position:relative;float:right;text-decoration:none;margin:1px 0 0;transition:color .17s ease}
.cloud-label li{position:relative;float:left;margin:0 5px 5px 0}
.cloud-label li a{display:block;height:26px;background-color:$(button3.bg);color:$(button3.color);font-size:12px;line-height:26px;font-weight:400;padding:0 10px;border-radius:2px;transition:all .17s ease}
.cloud-label li a:hover{background-color:$(button1.bg);color:$(button1.color)}
.cloud-label .label-count{display:none}
.BlogSearch .search-form{display:flex}
.BlogSearch .search-input{float:left;width:100%;height:30px;background-color:rgba(255,255,255,0.05);font-family:inherit;font-weight:400;font-size:12px;color:$(body.text.color);line-height:30px;box-sizing:border-box;padding:0 10px;margin:0 5px 0 0;border:1px solid rgba(155,155,155,0.17);border-radius:2px}
.BlogSearch .search-action{float:right;width:auto;height:30px;font-family:inherit;font-size:11px;font-weight:700;line-height:30px;text-transform:uppercase;cursor:pointer;box-sizing:border-box;background-color:$(button1.bg);color:$(button1.color);padding:0 15px;border:0;border-radius:2px;transition:all .17s ease}
.BlogSearch .search-action:hover{background-color:$(button2.bg);color:$(button2.color)}
.Profile .profile-img-wrap{float:left;width:88px;height:88px;background-color:#f9f9f9;color:transparent!important;margin:0 12px 0 0}
.Profile .no-snippet .profile-img-wrap{width:60px;height:60px}
.Profile .profile-img{display:block;width:100%;height:100%}
.Profile .profile-name-link{display:block;overflow:hidden;font-size:16px;color:$(link.color);font-weight:700;margin:0 0 5px;transition:color .17s ease}
.Profile .profile-name-link:hover{color:$(link.hover.color)}
.Profile .profile-snippet{overflow:hidden;font-size:12px;color:#888;line-height:1.4em;margin:0 0 5px}
.Profile .profile-link{font-size:12px;color:$(footer.hover.color)}
.Profile .profile-link:hover{text-decoration:underline}
.speedify-widget-ready .PageList ul,.speedify-widget-ready .LinkList ul{display:flex;flex-wrap:wrap}
.speedify-widget-ready .PageList ul li,.speedify-widget-ready .LinkList ul li{display:flex;flex-direction:column;width:50%;box-sizing:border-box;padding:0 5px 0 0}
.speedify-widget-ready .PageList ul li:nth-child(2n),.speedify-widget-ready .LinkList ul li:nth-child(2n){padding:0 0 0 5px}
.speedify-widget-ready .PageList ul li a,.speedify-widget-ready .LinkList ul li a{display:block;color:$(link.color);font-size:12px;font-weight:400;padding:8px 0 0;margin:8px 0 0;border-top:1px dashed rgba(155,155,155,0.17);transition:color .17s ease}
.speedify-widget-ready .PageList ul li:nth-child(1) a,.speedify-widget-ready .PageList ul li:nth-child(2) a,.speedify-widget-ready .LinkList ul li:nth-child(1) a,.speedify-widget-ready .LinkList ul li:nth-child(2) a{padding:0;margin:0;border:0}
.speedify-widget-ready .PageList ul li a:hover,.speedify-widget-ready .LinkList ul li a:hover{color:$(link.hover.color)}
.Text .widget-content{font-size:13px;line-height:1.6em}
.Image .image-caption{font-size:13px;line-height:1.6em;margin:10px 0 0;display:block}
.contact-form-widget form{font-family:inherit;font-weight:400}
.contact-form-name{float:left;width:100%;height:32px;background-color:rgba(255,255,255,0.05);font-family:inherit;font-size:13px;color:$(body.text.color);line-height:32px;box-sizing:border-box;padding:5px 10px;margin:0 0 10px;border:1px solid rgba(155,155,155,0.17);border-radius:2px}
.contact-form-email{float:left;width:100%;height:32px;background-color:rgba(255,255,255,0.05);font-family:inherit;font-size:13px;color:$(body.text.color);line-height:32px;box-sizing:border-box;padding:5px 10px;margin:0 0 10px;border:1px solid rgba(155,155,155,0.17);border-radius:2px}
.contact-form-email-message{float:left;width:100%;background-color:rgba(255,255,255,0.05);font-family:inherit;font-size:13px;color:$(body.text.color);box-sizing:border-box;padding:5px 10px;margin:0 0 10px;border:1px solid rgba(155,155,155,0.17);border-radius:2px}
.contact-form-button-submit{float:left;width:100%;height:32px;background-color:$(button1.bg);font-family:inherit;font-size:12px;color:$(button1.color);font-weight:700;line-height:32px;text-transform:uppercase;cursor:pointer;box-sizing:border-box;padding:0 10px;margin:0;border:0;border-radius:2px;transition:all .17s ease}
.contact-form-button-submit:hover{background-color:$(button2.bg);color:$(button2.color)}
.contact-form-error-message-with-border{float:left;width:100%;background-color:#fbe5e5;font-size:11px;color:#333;text-align:center;line-height:11px;padding:3px 0;margin:10px 0;box-sizing:border-box;border:1px solid #fc6262}
.contact-form-success-message-with-border{float:left;width:100%;background-color:#eaf6ff;font-size:11px;color:#333;text-align:center;line-height:11px;padding:3px 0;margin:10px 0;box-sizing:border-box;border:1px solid #5ab6f9}
.contact-form-cross{margin:0 0 0 3px}
.contact-form-error-message,.contact-form-success-message{margin:0}
#footer-wrapper{background-color:$(footer.bg);box-shadow:0 0 3px rgba(0,0,0,0.05)}
#footer-wrapper > .container{position:relative;overflow:hidden;margin:0 auto}
.footer-widgets-wrap{position:relative;display:flex;margin:0 -15px}
#footer-wrapper .footer{display:inline-block;float:left;width:33.33333333%;box-sizing:border-box;padding:30px 15px}
#footer-wrapper .footer.no-items{padding:0 15px}
#footer-wrapper .footer .widget{float:left;width:100%;padding:0;margin:30px 0 0}
#footer-wrapper .footer .widget:first-child{margin:0}
#footer-wrapper .footer .about-text{margin:10px 0 0}
.footer .widget > .widget-title > h3{position:relative;color:$(footer.color);font-size:17px;line-height:17px;font-weight:700;margin:0 0 20px}
.footer .about-text > .widget-title{display:none}
.footer .loader{height:145px}
.footer .no-posts{color:$(footer.text.color)}
.footer .post-image,.footer .Profile .profile-img-wrap,.footer .insta-widget .insta-image{background-color:rgba(155,155,155,0.06)}
.footer .PopularPosts .widget-content .post:first-child,.footer .custom-widget li:first-child,.footer .cmm-widget li:first-child{padding:0}
.footer .post-title,.footer .LinkList ul li a,.footer .PageList ul li a,.footer .Profile .profile-name-link{color:$(footer.color)}
.footer .post-link:hover .post-title{color:$(footer.post.title.hover.color)}
.footer .LinkList ul li a:hover,.footer .PageList ul li a:hover,.footer .Profile .profile-name-link:hover{color:$(footer.hover.color)}
.footer .follow-by-email-title{color:$(footer.color)}
.footer .FollowByEmail .widget-content{background-color:rgba(155,155,155,0.06);border:0}
.footer .follow-by-email-text,.footer .Profile .profile-snippet,.footer .Text .widget-content,.footer .Image .image-caption{color:$(footer.text.color)}
.footer .follow-by-email-address{color:$(footer.color);background-color:rgba(155,155,155,0.06);border-color:rgba(155,155,155,0.06)}
.footer .list-label li a,.footer .archive-list li a,.footer .PageList ul li a,.footer .LinkList ul li a{border-color:rgba(155,155,155,0.06)}
.footer .list-label li a,.footer .list-label li a:before,.footer .archive-list li a,.footer .archive-list li a:before{color:$(footer.color)}
.footer .list-label li > a:hover,.footer .archive-list li > a:hover,.footer .Text .widget-content a{color:$(footer.hover.color)}
.footer .cloud-label li a{background-color:rgba(155,155,155,0.06);color:$(footer.color)}
.footer .cloud-label li a:hover{background-color:$(button1.bg);color:$(button1.color)}
.footer .BlogSearch .search-input{background-color:rgba(155,155,155,0.06);color:$(footer.color);border-color:rgba(155,155,155,0.06)}
.footer .contact-form-name,.footer .contact-form-email,.footer .contact-form-email-message{background-color:rgba(155,155,155,0.06);color:$(footer.color);border-color:rgba(155,155,155,0.06)}
.footer .BlogSearch .search-action:hover,.footer .FollowByEmail .follow-by-email-inner .follow-by-email-submit:hover,.footer .contact-form-button-submit:hover{background-color:$(button1.bg);color:$(button1.color);opacity:.8}
#sub-footer-wrapper{display:block;width:100%;background-color:$(footer.bar.bg);color:$(footer.bar.color);overflow:hidden}
#sub-footer-wrapper .container{padding:13px 0;margin:0 auto;overflow:hidden}
#social-footer{float:right;position:relative;display:block}
#social-footer .widget > .widget-title{display:none}
#social-footer ul li{float:left;display:inline-block;height:30px;padding:0;margin:0}
#social-footer ul li a{font-size:13px;font-weight:400;display:block;color:$(footer.bar.color);line-height:30px;padding:0 8px;margin:0 0 0 5px;transition:color .17s ease}
#social-footer ul li:last-child a{padding-right:0}
#social-footer ul li a:hover{color:$(footer.bar.hover.color)}
#sub-footer-wrapper .copyright-area{font-size:12px;float:left;height:30px;line-height:30px;font-weight:400}
#sub-footer-wrapper .copyright-area a{color:$(footer.bar.color);transition:color .17s}
#sub-footer-wrapper .copyright-area a:hover{color:$(footer.bar.hover.color);text-decoration:underline}
.hidden-widgets{display:none;visibility:hidden}
.back-top{display:none;position:fixed;bottom:25px;right:25px;width:30px;height:30px;background-color:$(button1.bg);cursor:pointer;overflow:hidden;font-size:13px;color:$(button1.color);text-align:center;line-height:30px;z-index:2;border-radius:2px;transition:background .17s ease}
.back-top:after{content:'\f077';position:relative;font-family:'Font Awesome 5 Free';font-weight:900;transition:opacity .17s ease}
.error404 #main-wrapper{width:100%}
.error404 #sidebar-wrapper{display:none}
.errorWrap{color:$(link.color);text-align:center;padding:40px 0 100px}
.errorWrap h3{font-size:160px;line-height:1em;margin:0 0 20px}
.errorWrap h4{font-size:25px;margin:0 0 20px}
.errorWrap p{margin:0 0 10px}
.errorWrap a{display:inline-block;height:32px;background-color:$(button1.bg);font-size:12px;color:$(button1.color);font-weight:700;text-transform:uppercase;line-height:33px;padding:0 20px;margin:15px 0 0;border-radius:2px;transition:background .17s ease}
.errorWrap a:hover{background-color:$(button2.bg);color:$(button2.color)}
@media screen and (max-width: 1120px) {
#outer-wrapper{max-width:100%}
.row-x1{width:100%}
.header-content,#content-wrapper,#footer-wrapper > .container,#sub-footer-wrapper{box-sizing:border-box;padding:0 20px}
}
@media screen and (max-width: 980px) {
.nav-active #outer-wrapper{position:fixed;width:100%;overflow:hidden;filter:blur(2px)}
.nav-active{position:fixed;width:100%;overflow:hidden}
.nav-active .back-top{opacity:0!important}
#outer-wrapper{transition:filter .17s ease}
.header-content{padding:0}
.overlay{visibility:visible}
.show-mobile-menu,.slide-menu{display:block}
.show-search,.hide-search{width:auto;padding:0 20px;text-align:center}
#nav-search .search-input{padding:0 50px 0 20px}
.header-menu,.speedify-main-menu{display:none}
.main-logo{width:100%;text-align:center;z-index:15;margin:0}
.header-logo{width:100%;max-width:none}
.header-logo .header-widget,.header-logo .header-logo-image{float:none;display:inline-block}
#main-wrapper,#sidebar-wrapper{width:100%}
#sidebar-wrapper{margin:25px 0 0}
.featured-section .FeaturedPost .post,.index-post-wrap,.FollowByEmail .fbm-ify .widget-content-inner{padding:15px}
.item-post-inner,#related-wrap{padding:0 15px}
#blog-pager{padding:0 15px;margin:10px 0 15px}
#comments,#disqus_thread,.fb-comments,#gpluscomments{padding:15px!important}
}
@media screen and (max-width: 880px) {
.footer-widgets-wrap{display:block;overflow:hidden;padding:30px 0 0}
#footer-wrapper .footer{width:100%;padding:0 15px 30px}
#footer-wrapper .footer.no-items{padding:0 15px}
}
@media screen and (max-width: 680px) {
#sub-footer-wrapper .container{padding:20px 0}
#social-footer,#sub-footer-wrapper .copyright-area{width:100%;height:auto;line-height:inherit;text-align:center}
#social-footer ul li{float:none;height:auto}
#social-footer ul li a{line-height:inherit;margin:0 5px}
#sub-footer-wrapper .copyright-area{padding:20px 0 0}
}
@media screen and (max-width: 580px) {
.featured-section .FeaturedPost .post-image-wrap{height:250px}
.index-post .post-image-wrap{width:100%;height:200px;margin:0 0 10px}
.index-post .post-content{float:left}
}
@media screen and (max-width: 540px) {
.post-labels{margin:0 0 20px}
.post-labels span,.post-labels a{margin:0 5px 5px 0}
.related-posts{display:block}
.related-posts .related-item{display:block;width:100%;margin:15px 0 0}
.related-posts .item-0{margin:0}
.related-posts .post-link{display:block}
.related-posts .post-image{float:left;overflow:visible;width:80px;height:65px;margin:0 10px 0 0}
.related-posts .post-header{overflow:hidden;margin:0}
.queryMessage{height:auto;text-align:center;line-height:inherit;padding:10px}
.queryMessage a.show-more{width:100%;margin:10px 0 0}
}
@media screen and (max-width: 440px) {
.featured-section .FeaturedPost .post-image-wrap{height:220px}
.featured-section .FeaturedPost .post-title,.index-post .post-header .post-title,.item-post h1.post-title{font-size:25px}
.post-share{margin:0 0 18px}
.share-links li{margin:0 7px 7px 0}
.post-header .post-share{margin:13px 0 0}
.post-header .share-links li{margin:7px 7px 0 0}
.about-author .avatar-container{width:55px;height:55px;margin:0 15px 0 0}
.author-name{font-size:18px}
.author-name span{display:none}
}
@media screen and (max-width: 360px) {
.featured-section .FeaturedPost .post-image-wrap{height:200px}
.index-post .post-image-wrap{height:180px}
.featured-section .FeaturedPost .post-title,.index-post .post-header .post-title,.item-post h1.post-title{font-size:21px}
.slide-menu{width:270px}
.share-links li a,.share-links li span{width:30px;height:30px;line-height:30px}
.share-links li span{line-height:28px}
.share-links li span:after{top:10px}
.errorWrap h3{font-size:130px}
}

b:if.b:template-skin:
/*------Layout (No Edit)----------*/
body#layout #outer-wrapper,body#layout .row{width:auto;padding:0}
body#layout{width:920px;position:relative;background-color:#f9f9f9;padding:95px 5px 0;margin:0}
body#layout:before{content:'Theme Options - v2.0';position:absolute;top:0;left:5px;right:5px;height:95px;font-family:Roboto,sans-serif;font-size:23px;color:#1f2024;line-height:95px;text-align:center}
body#layout div.section{background-color:#f1f1f1!important;margin:0 5px 10px!important;padding:16px 16px 18px!important;border-color:#e5e5e5}
body#layout .section h4{font-size:14px;color:#1f2024;text-transform:uppercase;margin:0}
body#layout .add_widget a{color:#1bbc9b!important}
body#layout .widget-wrap3{overflow:hidden}
body#layout .widget-content{width:auto;max-width:none;max-height:none;margin:0;border:1px solid #e5e5e5;border-left:0}
body#layout .locked-widget .widget-content{border-left:1px solid #1bbc9b}
body#layout .locked-widget .widget-content:hover{border-left-color:#F4836A}
body#layout .widget .widget-content a.editlink{border-radius:2px}
body#layout .visibility .editlink{background:#1bbc9b url(https://1.bp.blogspot.com/-iQoCOwqjB-w/Wy1bDznOM4I/AAAAAAAACGA/8BUOPStr0sk5oud9hWpHBQTrmkeJDoAvACK4BGAYYCw/s18-c/mode_edit_w600_24dp.png) no-repeat center!important}
body#layout .visibility .editlink:hover{background-color:#F4836A!important}
body#layout .draggable-widget .widget-wrap2{background:#1bbc9b url(https://1.bp.blogspot.com/-yTAuT5aZ1EY/Wy1eEeo4SbI/AAAAAAAACGM/FxOTPwL-Ch0_lyZxLRzhv2EWHINOmCjWACK4BGAYYCw/s22/draggable.png) no-repeat 4px 50%!important}
body#layout .draggable-widget .widget-wrap1:hover .widget-wrap2{background-color:#F4836A!important}
body#layout .visibility .layout-widget-state.visible{background-image:url(https://2.bp.blogspot.com/-LpToxwoiieQ/Wy2ZEUsVesI/AAAAAAAACGY/lnRX3o6kczMOm1VnxOzlZ-WKzo_srca2QCK4BGAYYCw/s24-c/visibility_c1_600_24dp.png)!important}
body#layout .visibility .layout-widget-state.not-visible{background-image:url(https://2.bp.blogspot.com/-5Wlth_eaQKE/Wy2ZfHNqNoI/AAAAAAAACGk/WjBMhUIOOgEN6axAlWcXsNk8D3PHlFmbQCK4BGAYYCw/s24-c/visibility_off_c2_600_24dp.png)!important;opacity:1}
body#layout .layout-widget-description{display:none}
body#layout .theme-options,body#layout #speedify-main-menu .widget{display:block!important}
body#layout div.ify-panel,body#layout #mobile-options .section{background-color:#edf4ff!important;overflow:hidden!important;border-color:#cdd4ef}
body#layout .ify-panel .widget{float:left;width:32%;margin-right:2%}
body#layout .ify-panel .widget-content{border-color:#cdd4ef!important}
body#layout .ify-panel #LinkList151{margin-right:0}
body#layout #mobile-options{display:flex!important;height:auto;}
body#layout #mobile-options .section{width:50%}
body#layout .header-content > .container{display:flex;padding:0}
body#layout .header-menu,body#layout .main-logo{width:50%}
body#layout #speedify-main-menu,body#layout .header-logo{height:auto}
body#layout .header-logo{max-width:none;max-height:none}
body#layout #content-wrapper{margin:0}
body#layout #content-wrapper > .container{display:flex;margin:0}
body#layout #main-wrapper{width:67%;padding:0}
body#layout #sidebar-wrapper{width:33%;padding:0}
body#layout #custom-ads{display:block!important;display:flex!important}
body#layout #custom-ads .section{width:50%}
body#layout .footer-widgets-wrap{display:flex}
body#layout .footer-widgets-wrap div.footer{width:100%}

/*------Layout (end)----------*/

head.script:
